changeSet.sql:
INSERT INTO document_type (company_id, code, name, category, description, provider_code, system_managed, active, created_at, updated_at)
SELECT NULL, 'PURCHASE_ORDER', 'Purchase Order', 'PROCUREMENT', 'Purchase order document templates', 'PURCHASE_ORDER', TRUE, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM document_type WHERE company_id IS NULL AND code = 'PURCHASE_ORDER');
INSERT INTO document_type (company_id, code, name, category, description, provider_code, system_managed, active, created_at, updated_at)
SELECT NULL, 'PURCHASE_REQUISITION', 'Purchase Requisition', 'PROCUREMENT', 'Purchase requisition document templates', 'PURCHASE_REQUISITION', TRUE, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM document_type WHERE company_id IS NULL AND code = 'PURCHASE_REQUISITION');
